 private void alarms(){final SharedPreferences p=SoundSchedule.prefs(this);final org.json.JSONArray alarms=AlarmScheduler.alarms(this);final Set<String> ids=new HashSet<String>(p.getStringSet("alarm-ids",Collections.<String>emptySet()));ArrayList<String> labels=new ArrayList<String>();labels.add(p.getBoolean("selected-alarms",false)?"Doar alarmele selectate":"Toate alarmele Leo");for(int i=0;i<alarms.length();i++){org.json.JSONObject a=alarms.optJSONObject(i);labels.add((ids.contains(""+a.optInt("id"))?"✓ ":"")+a.optString("label","Alarmă")+" · "+SoundScheduleMath.format(a.optInt("hour")*60+a.optInt("minute")));}list("Excepții alarme Leo",labels,0,new Choice(){public void pick(int i){if(i==0)p.edit().putBoolean("selected-alarms",!p.getBoolean("selected-alarms",false)).apply();else{String id=""+alarms.optJSONObject(i-1).optInt("id");if(!ids.remove(id))ids.add(id);p.edit().putStringSet("alarm-ids",ids).apply();}alarms();}},"Înapoi",new Runnable(){public void run(){show();}});back=new Runnable(){public void run(){show();}};}
